package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveEntry_equals_TriageGen1Test {

    @Test
    public void testEquals_SameInstance() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertTrue(entry.equals(entry));
    }

    @Test
    public void testEquals_Null() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertFalse(entry.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        String other = "test.txt";
        assertFalse(entry.equals(other));
    }

    @Test
    public void testEquals_BothNamesNull() {
        // To achieve myName == null and otherName == null
        // We use the protected constructor or a way to have a null name
        // Since the constructor sets the name, we rely on the behavior of getName()
        ZipArchiveEntry entry1 = new ZipArchiveEntry(null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry(null);

        // Based on the provided logic:
        // if (myName == null) { if (otherName != null) return false; }
        // if both are null, it skips the inner if and returns true.
        assertTrue(entry1.equals(entry2));
    }

    @Test
    public void testEquals_MyNameNull_OtherNameNotNull() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry(null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_MyNameNotNull_TriggersElseIf() {
        // The provided code has a very specific logic:
        // else if (!false) { return false; }
        // Since !false is always true, if myName is NOT null, it will ALWAYS return false.
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");

        // Even though names are the same, the provided implementation's 
        // 'else if (!false)' branch forces a return false.
        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_MyNameNotNull_OtherNameNull() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry(null);

        // myName is not null -> enters else if (!false) -> returns false
        assertFalse(entry1.equals(entry2));
    }
}
